const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)||'null')||fallback;}catch(_){return fallback;}};
let store=read(KEY,{version:3,courses:{},cursor:{},selectedAge:4,muted:false}),old=read(OLD,{}),pref=read(PREF,{film:'song'});store.courses||={};store.cursor||={};
let course,legacy,module,plan,state,flow,nodes=[],paused=false,token=0,delay=null,pending=null,lastId=null,round=0,repeats=0,ready=false,covered=false,video=false,filmFrame=0,paint='#537f65',select=null,playing=false,screen='lesson',lastFocus=null,storageOK=true;
const meta=id=>window.CLASSROOM_LITERACY_AUDIO?.[id]||window.CLASSROOM_VARIETY_AUDIO?.[id]||window.CLASSROOM_PICTURE_AUDIO?.[id]||window.CLASSROOM_TODDLER_AUDIO?.[id]||window.CLASSROOM_LANGUAGE_AUDIO?.[id]||window.CLASSROOM_FILM_AUDIO?.[id]||PICNIC_PROMPTS[id]||window.CLASSROOM_AUDIO?.[id]||COURSE_AUDIO[id]||ACADEMY_AUDIO[id];
const node=()=>nodes[flow.index];
function save(){window.IslandRewards?.preserve(store);if(!course)return;state.updatedAt=Date.now();state.flow=flow;store.courses[course.id]=state;store.selectedAge=course.age;store.cursor[course.age]=course.id;try{localStorage.setItem(KEY,JSON.stringify(store));localStorage.setItem(PREF,JSON.stringify(pref));storageOK=true;}catch(_){storageOK=false;}}
function stop(){token++;clearTimeout(delay?.handle);delay=null;if(pending){const r=pending;pending=null;r(false);}voice.pause();voice.onended=voice.onerror=null;PicnicSpeaking.clear();motion?.cancel();playing=false;ready=false;round=repeats=0;}
function wait(ms,t=token){return new Promise(r=>{if(t!==token)return r(false);pending=r;delay={remaining:ms,due:performance.now()+ms,fire(){delay=null;pending=null;r(t===token);}};if(!paused)delay.handle=setTimeout(delay.fire,ms);});}
function status(s){const e=document.getElementById('uStatus');if(e)e.textContent=s;}
let noteContext=null;
function beat(i){if(i===2)return;try{noteContext||=new AudioContext();noteContext.resume();const o=noteContext.createOscillator(),g=noteContext.createGain();o.frequency.value=i===1?250:440;g.gain.value=.07;o.connect(g);g.connect(noteContext.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,noteContext.currentTime+.16);o.stop(noteContext.currentTime+.18);}catch(_){} }
function caption(s,h){const e=document.getElementById('uCaption');if(e)e.textContent=s;if(h!=null){const p=document.getElementById('uHint');if(p)p.textContent=h;}}
function retrySound(){if(!root.querySelector('.u-sound-gate')){root.insertAdjacentHTML('beforeend','<div class="u-sound-gate" role="region" aria-label="开启课堂声音"><div><span aria-hidden="true">♫</span><h2>一起开始有声课堂</h2><p>点一下，让故事和提示读给你听。</p>'+btn('soundStart','▶ 开始有声课堂')+'</div></div>');root.querySelector('[data-u="soundStart"]')?.focus();}}
function play(id,t=token){return new Promise(r=>{if(t!==token)return r(false);const a=meta(id);lastId=id;pending=r;if(!a){pending=null;status('声音未就绪，点重听或查看字幕');return r(false);}voice.src='assets/'+a.src;voice.defaultPlaybackRate=a.locale?.startsWith('en')&&flow.slow?.85:1;voice.playbackRate=voice.defaultPlaybackRate;
 const end=ok=>{if(t!==token)return;pending=null;playing=false;document.querySelectorAll('.is-speaking').forEach(e=>e.classList.remove('is-speaking'));r(ok);};voice.onended=()=>end(true);voice.onerror=()=>{status('声音暂时没加载，点重听再试');retrySound();end(false);};
 if(store.muted){status('声音已关闭');wait(Math.max(500,a.duration*1000),t).then(ok=>{if(t===token){pending=null;r(ok);}});return;}
 if(!paused)voice.play().then(()=>{if(t!==token)return;playing=true;root.querySelector('.u-sound-gate')?.remove();root.querySelectorAll('.focus-target').forEach(e=>e.classList.add('is-speaking'));status(id.startsWith('CLASS-instruction')?'先听玩法提示':node().kind==='model'||node().kind==='en-game'?`第 ${round||1} / ${repeats||2} 遍`:'听一听，慢慢来');}).catch(e=>{if(t!==token)return;if(e.name!=='AbortError'){status(e.name==='NotAllowedError'?'点一下开始声音':'声音暂时没加载，点重听再试');retrySound();end(false);}});
 });}
async function repeat(id,t=token){repeats=2;for(let i=1;i<=2;i++){round=i;status(`第 ${i} / 2 遍`);if(!await play(id,t))return false;if(i===1&&!await wait(1200,t))return false;}return t===token;}
function buildNodes(){const out=[],add=x=>out.push(x);if(legacy){legacy.opening.forEach((x,i)=>add({group:0,kind:'story',clip:x.id,text:x.text,phase:'opening',frame:i,pack:legacy.id==='01'&&i===0}));const teaching=legacy.id==='01'?[...legacy.teaching.slice(1),legacy.teaching[0]]:legacy.teaching;teaching.forEach(x=>add({group:0,kind:'story',clip:x.id,text:x.text,phase:'teach',frame:x.visualStep??legacy.teaching.indexOf(x)}));}else add({group:0,kind:'story',clip:module.audio.zh,text:course.concept,phase:'method',frame:0});
 add({group:1,kind:'task',text:course.task});if(legacy)legacy.film.forEach((x,i)=>add({group:2,kind:'film',clip:x.id,text:x.text,phase:'film',frame:i}));else add({group:2,kind:'film',clip:'ACADEMY-ready',text:course.concept,frame:0});
 plan.models.forEach(({id,focus,skip})=>add({group:3,kind:'model',clip:id,target:focus,text:meta(id).text,skip:!!skip}));plan.englishGames.forEach((mode,i)=>add({group:3,kind:'en-game',mode,text:course.english,game:i,skip:course.age===3&&i>0}));
 if(legacy)add({group:4,kind:'move',clip:legacy.movement[0]?.id,text:'跟着朋友动一动，活动好了再回来。',phase:'move',frame:0});add({group:4,kind:'life',text:course.extension,clip:legacy?legacy.home[0]?.id:null});
 if(legacy)legacy.ending.forEach((x,i)=>add({group:4,kind:'ending',clip:x.id,text:x.text,phase:'ending',frame:i}));else add({group:4,kind:'ending',clip:'ACADEMY-reflect',text:course.concept});add({group:5,kind:'done'});if(course.age===3){let seen=false;for(const n of out){if(n.group===0){n.skip=seen;if(!seen){n.clip='FILM-'+course.id;n.text=meta(n.clip)?.text||course.task;seen=true;}}}}return out;}
function activate(id){window.RewardCelebration?.close();pendingStageFood=0;stop();course=D.courses.find(c=>c.id===id)||D.courses.find(c=>c.id==='P04-01');legacy=COURSES.lessons.find(l=>l.id===course.existingCourseId);module=D.modules[course.id];plan=CLASSROOM_PLAN[course.id];state=store.courses[course.id]||{stage:0,stages:{},finished:false,observation:'',elapsed:0};state.stages||={};state.english||={};
 flow=state.flow?.version===1?state.flow:{version:1,index:0,completed:[],english:{},design:{},slow:false,packed:[],game:legacy?(old.courses?.[legacy.id]?.game||LE.create(legacy.mode,0,legacy.gameConfig)):null};flow.english||={};if(flow.experienceVersion!==2){{const previousGames=Object.fromEntries(Object.entries(flow.english).filter(([key])=>!key.startsWith('model-')));if(Object.keys(previousGames).length)flow.previousEnglishGames=previousGames;for(const key of Object.keys(previousGames))delete flow.english[key];}flow.experienceVersion=2;}if(flow.languageVersion!==3){if(course.age>=4){flow.previousLanguageGames=Object.fromEntries(Object.entries(flow.english).filter(([k])=>/^\d+$/.test(k)));for(const k of Object.keys(flow.previousLanguageGames))delete flow.english[k];}flow.languageVersion=3;}flow.design||={};flow.completed||=[];flow.packed||=[];window.ClassroomVariety?.migrate(flow);
 if(legacy&&(!flow.game||flow.game.mode!==legacy.mode))flow.game=LE.create(legacy.mode,0,legacy.gameConfig);if(!legacy&&!state.activity)state.activity=AE.create(module);if(window.ClassroomPictureStory?.matches(course)){state.activity=ClassroomPictureStory.migrate(flow,state.activity);if(!state.activity.done)delete state.stages[2];}nodes=buildNodes();
 if(!state.flow){const group=legacy?({0:0,1:0,2:1,3:2,4:3,5:4,6:4,7:4}[old.courses?.[legacy.id]?.chapter]??0):[0,0,1,2,3,4,4][state.stage||0];flow.index=Math.max(0,nodes.findIndex(x=>x.group===group));}
 flow.index=Math.max(0,Math.min(nodes.length-1,Number(flow.index)||0));while(nodes[flow.index]?.skip&&flow.index<nodes.length-1)flow.index++;document.getElementById('uAge').textContent=`${course.age} 岁 · 第 ${course.sequence} / 20 关`;document.title=course.title+' · 小小奇遇岛';screen='lesson';save();render();run();}
function groupNames(){return course.age<=6?['听故事','动手玩','看短片','说英语','生活里试试']:['问题与方法','动手挑战','短片欣赏','英语任务','实践与回顾'];}
